package cn.corenyan.matrix;
import android.content.*;import android.database.*;import android.net.Uri;import android.os.ParcelFileDescriptor;import android.provider.OpenableColumns;import java.io.*;import org.json.*;
public final class UploadProvider extends ContentProvider {
 @Override public boolean onCreate(){return true;}
 private File directory(Uri uri)throws FileNotFoundException{String id=uri.getLastPathSegment();if(id==null||!id.matches("[a-f0-9-]{36}"))throw new FileNotFoundException();File dir=new File(new File(getContext().getCacheDir(),"uploads"),id);if(!new File(dir,"payload").isFile()||!new File(dir,"meta.json").isFile())throw new FileNotFoundException();return dir;}
 private JSONObject metadata(Uri uri)throws Exception{try(InputStream in=new FileInputStream(new File(directory(uri),"meta.json"))){ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] b=new byte[1024];int n;while((n=in.read(b))!=-1){if(bytes.size()+n>8192)throw new IOException();bytes.write(b,0,n);}return new JSONObject(bytes.toString("UTF-8"));}}
 @Override public String getType(Uri uri){try{return metadata(uri).getString("mime");}catch(Exception e){return "application/octet-stream";}}
 @Override public ParcelFileDescriptor openFile(Uri uri,String mode)throws FileNotFoundException{if(!"r".equals(mode))throw new FileNotFoundException();return ParcelFileDescriptor.open(new File(directory(uri),"payload"),ParcelFileDescriptor.MODE_READ_ONLY);}
 @Override public Cursor query(Uri uri,String[] projection,String selection,String[] args,String order){try{File payload=new File(directory(uri),"payload");JSONObject m=metadata(uri);String[] columns=projection==null?new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE}:projection;MatrixCursor c=new MatrixCursor(columns);Object[] row=new Object[columns.length];for(int i=0;i<columns.length;i++)row[i]=OpenableColumns.SIZE.equals(columns[i])?payload.length():OpenableColumns.DISPLAY_NAME.equals(columns[i])?m.getString("name"):null;c.addRow(row);return c;}catch(Exception e){return null;}}
 @Override public Uri insert(Uri uri,ContentValues values){throw new UnsupportedOperationException();}@Override public int update(Uri uri,ContentValues values,String s,String[] a){throw new UnsupportedOperationException();}@Override public int delete(Uri uri,String s,String[] a){throw new UnsupportedOperationException();}
}
